## 1. Compreensão do problema

O grafo representa as ilhas, e cada barco é uma aresta não direcionada cujo peso é sua capacidade de passageiros. Para cada consulta `(X, Y)`, queremos encontrar o maior valor `K` tal que exista um caminho de `X` até `Y` em que **todas** as arestas tenham capacidade de pelo menos `K`.

O formato da entrada é um único grafo com `N` vértices e `B` arestas, seguido de `C` consultas. Para cada consulta, a saída deve conter uma linha com a maior capacidade possível do grupo.

As restrições são `N, B ≤ 10^5` e `C ≤ 5 × 10^4`. Os pesos estão entre `1` e `10^5`; portanto, não há risco de overflow nas capacidades. O enunciado garante que é possível viajar entre quaisquer duas ilhas, então o grafo é conexo. Consultas com origem e destino iguais não ocorrem.

## 2. Planejamento e design algorítmico

Usaremos uma **árvore geradora máxima** e o **LCA com levantamento binário**.

A propriedade importante é: em uma árvore geradora máxima, o caminho entre dois vértices maximiza a menor capacidade das arestas entre todos os caminhos possíveis no grafo. Assim, basta encontrar a menor aresta no caminho entre as ilhas consultadas na árvore.

### Etapas

1. Ordenar as arestas em ordem decrescente de capacidade.
2. Aplicar Kruskal com Union-Find para construir uma árvore geradora máxima.
3. Enraizar a árvore e calcular, para cada vértice:
   - sua profundidade;
   - seus ancestrais `2^k` níveis acima;
   - a menor capacidade no trecho até cada um desses ancestrais.
4. Para cada consulta, usar levantamento binário para encontrar o LCA e a menor aresta no caminho.

A complexidade é **`O(B log B + (N + C) log N)`** em tempo e **`O(N log N + B)`** em memória.

## 3. Codificação em C

```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAXN 100000
#define MAXB 100000
#define LOG 20

typedef struct {
    int u, v, w;
} Edge;

static Edge edges[MAXB];

static int parent[MAXN + 1];
static int size_dsu[MAXN + 1];

static int head[MAXN + 1];
static int to[2 * MAXN];
static int weight[2 * MAXN];
static int next_edge[2 * MAXN];
static int edge_count;

static int depth[MAXN + 1];
static int up[LOG][MAXN + 1];
static int min_edge[LOG][MAXN + 1];
static int stack_nodes[MAXN + 1];

static int find_set(int x) {
    if (parent[x] != x) {
        parent[x] = find_set(parent[x]);
    }
    return parent[x];
}

static int unite(int a, int b) {
    a = find_set(a);
    b = find_set(b);

    if (a == b) {
        return 0;
    }

    if (size_dsu[a] < size_dsu[b]) {
        int temp = a;
        a = b;
        b = temp;
    }

    parent[b] = a;
    size_dsu[a] += size_dsu[b];
    return 1;
}

static int compare_edges_desc(const void *a, const void *b) {
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;

    if (ea->w > eb->w) return -1;
    if (ea->w < eb->w) return 1;
    return 0;
}

static void add_tree_edge(int u, int v, int w) {
    to[edge_count] = v;
    weight[edge_count] = w;
    next_edge[edge_count] = head[u];
    head[u] = edge_count++;

    to[edge_count] = u;
    weight[edge_count] = w;
    next_edge[edge_count] = head[v];
    head[v] = edge_count++;
}

static int min_int(int a, int b) {
    return (a < b) ? a : b;
}

static int query(int a, int b) {
    int answer = INT_MAX;

    if (depth[a] < depth[b]) {
        int temp = a;
        a = b;
        b = temp;
    }

    int difference = depth[a] - depth[b];

    for (int k = LOG - 1; k >= 0; --k) {
        if ((difference >> k) & 1) {
            answer = min_int(answer, min_edge[k][a]);
            a = up[k][a];
        }
    }

    if (a == b) {
        return answer;
    }

    for (int k = LOG - 1; k >= 0; --k) {
        if (up[k][a] != up[k][b]) {
            answer = min_int(answer, min_edge[k][a]);
            answer = min_int(answer, min_edge[k][b]);
            a = up[k][a];
            b = up[k][b];
        }
    }

    answer = min_int(answer, min_edge[0][a]);
    answer = min_int(answer, min_edge[0][b]);
    return answer;
}

int main(void) {
    int N, B;

    if (scanf("%d %d", &N, &B) != 2) {
        return 0;
    }

    for (int i = 0; i < B; ++i) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);
    }

    for (int i = 1; i <= N; ++i) {
        parent[i] = i;
        size_dsu[i] = 1;
        head[i] = -1;
    }

    qsort(edges, B, sizeof(Edge), compare_edges_desc);

    int selected = 0;
    for (int i = 0; i < B && selected < N - 1; ++i) {
        if (unite(edges[i].u, edges[i].v)) {
            add_tree_edge(edges[i].u, edges[i].v, edges[i].w);
            ++selected;
        }
    }

    /* Percorre a árvore para definir profundidades e ancestrais imediatos. */
    int stack_size = 0;
    int visited[MAXN + 1] = {0};

    stack_nodes[stack_size++] = 1;
    visited[1] = 1;
    depth[1] = 0;
    up[0][1] = 1;
    min_edge[0][1] = INT_MAX;

    while (stack_size > 0) {
        int u = stack_nodes[--stack_size];

        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];

            if (visited[v]) {
                continue;
            }

            visited[v] = 1;
            depth[v] = depth[u] + 1;
            up[0][v] = u;
            min_edge[0][v] = weight[e];
            stack_nodes[stack_size++] = v;
        }
    }

    for (int k = 1; k < LOG; ++k) {
        for (int v = 1; v <= N; ++v) {
            up[k][v] = up[k - 1][up[k - 1][v]];
            min_edge[k][v] = min_int(
                min_edge[k - 1][v],
                min_edge[k - 1][up[k - 1][v]]
            );
        }
    }

    int C;
    scanf("%d", &C);

    for (int i = 0; i < C; ++i) {
        int X, Y;
        scanf("%d %d", &X, &Y);
        printf("%d\n", query(X, Y));
    }

    return 0;
}
```

## 4. Retrospecto e verificação

A árvore geradora máxima preserva, entre cada par de ilhas, a maior capacidade mínima possível ao longo de um caminho. O levantamento binário calcula essa capacidade mínima sem percorrer todo o caminho para cada consulta.

No exemplo 1, a consulta entre `2` e `1` tem resposta `75`; entre `1` e `3`, a resposta é `60`, como esperado. O mesmo método também cobre árvores, grafos densos e capacidades repetidas.

A implementação percorre a árvore de forma iterativa, evitando problemas de estouro de pilha em árvores profundas. O limite `LOG = 20` é suficiente para `N ≤ 10^5`, e os arrays são dimensionados para a indexação de `1` a `N`.

